"use client"

import * as React from "react"
import { toast } from "sonner"

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { ScenarioIndex } from "@/components/mockups/live-scenarios/scenario-index"
import { ApprovalEditor } from "@/components/mockups/publish-approval/approval-editor"
import { ApprovalsPage } from "@/components/mockups/publish-approval/approvals-page"
import { ApprovalsIcon } from "@/components/mockups/publish-approval/icons"
import { ReviewDrawer } from "@/components/mockups/publish-approval/review-drawer"
import { StatusBadge } from "@/components/mockups/publish-approval/status-badge"
import { type Notice, Notifications } from "@/components/shared/notifications"
import { AppShell } from "@/components/shell/app-shell"
import { MockupShell } from "@/components/shell/mockup-shell"
import type { Subject } from "@/lib/mockups/config-versioning-data"
import { SCENARIOS, type ScenarioRow } from "@/lib/mockups/live-scenarios-data"
import {
  type ApprovalRequest,
  CASES,
  type CaseId,
  canDecide,
  canSee,
  changesBetween,
  forViewer,
  mainRequest,
  OTHER_REQUESTS,
  SCENARIO,
  type ViewerId,
  VIEWERS,
  who,
  withV15,
} from "@/lib/mockups/publish-approval-data"

/**
 * Publish approval — DES-204, under INT-253, for PLT-4477. The spec is the
 * "Publish approval" requirements doc and its two mockups (the Approvals
 * page and the bell); it sits on DES-202's versions (/config-versioning).
 * The TDD (22 Oct 2026) makes it a feature of its own, after live and
 * versioning ship; the first release has no approval.
 *
 * One state, two people. The reviewer switches between the requester
 * (Sarj) and the client's approver, and the same request moves between
 * them: send it as Ahmad, approve or reject it as Yusuf, see the outcome as
 * Ahmad. The views are the three places approval shows up —
 * the scenario editor, the scenarios index and Approvals — and the state
 * select reaches the cases the ticket names directly.
 */

const VIEWS = [
  { id: "editor", label: "Scenario" },
  { id: "index", label: "Scenarios" },
  { id: "approvals", label: "Approvals" },
] as const

type View = (typeof VIEWS)[number]["id"]

type World = { subject: Subject; requests: ApprovalRequest[] }

function initialWorld(caseId: CaseId): World {
  const others = caseId === "empty" ? [] : OTHER_REQUESTS
  switch (caseId) {
    case "pending":
    case "approve-fails":
      return {
        subject: SCENARIO,
        requests: [mainRequest("pending"), ...others],
      }
    case "newer":
      return {
        subject: withV15(SCENARIO),
        requests: [mainRequest("pending"), ...others],
      }
    case "rejected":
      return {
        subject: SCENARIO,
        requests: [
          mainRequest("rejected", 14, {
            by: "Yusuf Al-Amri",
            at: "Today, 11:02",
            reason:
              "Keep the 1 to 10 scale until the branch reports switch over on 1 November.",
          }),
          ...others,
        ],
      }
    default:
      return { subject: SCENARIO, requests: others }
  }
}

/** The index row for the scenario the editor shows, above DES-203's rows. */
const SCENARIO_ROW: ScenarioRow = {
  id: "bvs",
  name: SCENARIO.name,
  languages: ["AR", "EN"],
  created: "14 Sep 2026, 10:20",
  updated: "12 Oct 2026, 14:02",
  updatedBy: "akhalil",
  live: { by: "Nouf Al-Harbi", at: "15 Sep 2026, 09:00" },
}

export default function PublishApprovalPage() {
  const [caseId, setCaseId] = React.useState<CaseId>("normal")
  const [viewerId, setViewerId] = React.useState<ViewerId>("requester")
  const [view, setView] = React.useState<View>("editor")
  const [world, setWorld] = React.useState(() => initialWorld("normal"))
  const [open, setOpen] = React.useState<{ id: string; list: string[] } | null>(
    null,
  )
  const [read, setRead] = React.useState<Set<string>>(new Set())
  const viewer = VIEWERS.find((entry) => entry.id === viewerId)!

  /* A toast belongs to the case and person that raised it. */
  React.useEffect(() => {
    toast.dismiss()
  }, [caseId, viewerId])

  function pickCase(next: CaseId) {
    setCaseId(next)
    setWorld(initialWorld(next))
    setOpen(null)
    setRead(new Set())
    if (next === "approve-fails") setViewerId("approver")
    if (next === "load-fails" || next === "empty") setView("approvals")
    if (next !== "load-fails" && next !== "empty" && view === "approvals")
      setView("editor")
  }

  const { subject, requests } = world
  const visible = requests.filter((request) => canSee(request, viewer))
  const mine = requests.filter((request) => request.item === subject.name)
  const waitingOnMe = visible.filter(
    (request) => request.status === "pending" && canDecide(request, viewer),
  )

  /* An approver hears a request is waiting; a requester hears theirs was
     decided by someone else. */
  const notices: Notice[] = [
    ...waitingOnMe.map((request) => ({
      id: request.id,
      title: `${who(request.by, viewer)} wants to publish v${request.version}`,
      detail: request.item,
      at: request.raised,
    })),
    ...visible
      .filter(
        (request) =>
          request.by === viewer.name &&
          (request.status === "approved" || request.status === "rejected") &&
          request.decision &&
          request.decision.by !== viewer.name,
      )
      .map((request) => ({
        id: request.id,
        title: `${request.decision!.by} ${request.status} v${request.version}`,
        detail: request.item,
        at: request.decision!.at,
      })),
  ]

  /* ------------------------------------------------------------ actions */

  function update(id: string, change: Partial<ApprovalRequest>) {
    setWorld((current) => ({
      ...current,
      requests: current.requests.map((request) =>
        request.id === id ? { ...request, ...change } : request,
      ),
    }))
  }

  function save(
    body: Record<string, string>,
    editedFrom: number,
    note: string,
  ) {
    const n = subject.versions[0].n + 1
    setWorld((current) => ({
      ...current,
      subject: {
        ...current.subject,
        versions: [
          {
            n,
            author: viewer.name,
            mine: true,
            at: "Just now",
            editedFrom,
            note: note || null,
            body,
          },
          ...current.subject.versions,
        ],
      },
    }))
    return n
  }

  async function request(input: {
    version: number
    summary: string
    note: string
  }) {
    await new Promise((resolve) => setTimeout(resolve, 900))
    const live = subject.inUse
    const made: ApprovalRequest = {
      id: `bvs-${input.version}-${requests.length}`,
      item: subject.name,
      org: "Riyad Bank",
      version: input.version,
      live,
      by: viewer.name,
      raised: "Just now",
      waiting: "under a minute",
      note: input.note,
      summary: input.summary,
      changes: changesBetween(subject, live, input.version),
      status: "pending",
      decision: null,
    }
    setWorld((current) => ({
      ...current,
      /* One request at a time: a new one withdraws the one waiting. */
      requests: [
        made,
        ...current.requests.map((item) =>
          item.item === subject.name && item.status === "pending"
            ? {
                ...item,
                status: "withdrawn" as const,
                decision: { by: viewer.name, at: "Just now" },
              }
            : item,
        ),
      ],
    }))
    return true
  }

  async function approve(id: string) {
    await new Promise((resolve) => setTimeout(resolve, 900))
    const target = requests.find((item) => item.id === id)
    if (!target) return false
    const before = world
    setWorld((current) => ({
      requests: current.requests.map((item) =>
        item.id === id
          ? {
              ...item,
              status: "approved",
              decision: { by: viewer.name, at: "Just now" },
            }
          : item,
      ),
      /* Approving publishes: the version goes in use, and no version is
         made. */
      subject:
        target.item === current.subject.name
          ? {
              ...current.subject,
              inUse: target.version,
              log: [
                {
                  n: target.version,
                  by: viewer.name,
                  at: "just now",
                  how: "published",
                },
                ...current.subject.log,
              ],
            }
          : current.subject,
    }))
    setOpen(null)
    toast.success(`v${target.version} is in use`, {
      description: `Callers of ${target.item} get it from the next call.`,
      action: { label: "Undo", onClick: () => setWorld(before) },
    })
    return true
  }

  function reject(id: string, reason: string) {
    const target = requests.find((item) => item.id === id)
    update(id, {
      status: "rejected",
      decision: { by: viewer.name, at: "Just now", reason },
    })
    setOpen(null)
    toast(`Rejected v${target?.version}`, {
      description: `${target ? who(target.by, viewer) : "The requester"} sees your reason. Callers keep hearing v${target?.live}.`,
    })
  }

  function withdraw(id: string) {
    const target = requests.find((item) => item.id === id)
    update(id, {
      status: "withdrawn",
      decision: { by: viewer.name, at: "Just now" },
    })
    setOpen(null)
    toast(`Request for v${target?.version} withdrawn`, {
      action: {
        label: "Undo",
        onClick: () => update(id, { status: "pending", decision: null }),
      },
    })
  }

  /* Live is a switch and a badge with its own permission, never an
     approval, and the version in use does not change (TDD 3.1). */
  function toggleLive(on: boolean) {
    setWorld((current) => ({
      ...current,
      subject: {
        ...current.subject,
        live: on,
        toggled: { by: viewer.name, at: "just now" },
      },
    }))
  }

  /* -------------------------------------------------------------- page */

  const shown = open
    ? (requests.find((item) => item.id === open.id) ?? null)
    : null

  return (
    <MockupShell
      actions={
        <>
          <Select
            onValueChange={(value) => setViewerId(value as ViewerId)}
            value={viewerId}
          >
            <SelectTrigger aria-label="Viewing as" size="sm">
              <SelectValue />
            </SelectTrigger>
            <SelectContent align="end" position="popper">
              {VIEWERS.map((entry) => (
                <SelectItem key={entry.id} value={entry.id}>
                  {entry.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select
            onValueChange={(value) => pickCase(value as CaseId)}
            value={caseId}
          >
            <SelectTrigger aria-label="State" size="sm">
              <SelectValue />
            </SelectTrigger>
            <SelectContent align="end" position="popper">
              {CASES.map((entry) => (
                <SelectItem key={entry.id} value={entry.id}>
                  {entry.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <ToggleGroup
            aria-label="View"
            onValueChange={(next) => {
              if (next) setView(next as View)
            }}
            size="sm"
            type="single"
            value={view}
            variant="outline"
          >
            {VIEWS.map((entry) => (
              <ToggleGroupItem key={entry.id} value={entry.id}>
                {entry.label}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
        </>
      }
      title="Publish approval for live scenario changes"
    >
      <TooltipProvider>
        <AppShell
          active={view === "approvals" ? "Approvals" : "Scenarios"}
          addedItems={[
            {
              after: "Tasks",
              item: {
                icon: ApprovalsIcon,
                title: "Approvals",
                badge: waitingOnMe.length,
              },
            },
          ]}
          breadcrumb={
            view === "editor"
              ? ["Scenarios", subject.name]
              : view === "index"
                ? "Scenarios"
                : "Approvals"
          }
          onNavigate={(title) => {
            if (title === "Scenarios") setView("index")
            if (title === "Approvals") setView("approvals")
          }}
          scope={
            <Notifications
              notices={notices}
              onOpen={(id) => setOpen({ id, list: [id] })}
              onRead={(ids) =>
                setRead((current) => new Set([...current, ...ids]))
              }
              onViewAll={() => setView("approvals")}
              viewAll="Approvals"
              read={read}
            />
          }
        >
          {view === "editor" ? (
            <ApprovalEditor
              caseId={caseId}
              key={`${caseId}-${viewerId}`}
              onOpenRequest={(id) => setOpen({ id, list: [id] })}
              onRequest={request}
              onSave={save}
              onToggleLive={toggleLive}
              requests={mine}
              subject={forViewer(subject, viewer)}
              viewer={viewer}
            />
          ) : view === "index" ? (
            <ScenarioIndex
              marker={(row) => {
                const waiting = requests.find(
                  (item) => item.item === row.name && item.status === "pending",
                )
                if (!waiting) return null
                /* The chip is the flag; which version, and for how long,
                   is a hover away rather than another column. */
                return (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="flex" tabIndex={0}>
                        <StatusBadge status="pending" />
                      </span>
                    </TooltipTrigger>
                    <TooltipContent className="tabular-nums">
                      v{waiting.version} waiting {waiting.waiting} for{" "}
                      {waiting.org}’s approval
                    </TooltipContent>
                  </Tooltip>
                )
              }}
              rows={[SCENARIO_ROW, ...SCENARIOS]}
            />
          ) : (
            <ApprovalsPage
              caseId={caseId}
              key={`${caseId}-${viewerId}`}
              onOpen={(id, list) => setOpen({ id, list })}
              requests={visible}
              viewer={viewer}
            />
          )}

          <ReviewDrawer
            failApprove={caseId === "approve-fails"}
            list={open?.list ?? []}
            onApprove={approve}
            onClose={() => setOpen(null)}
            onReject={reject}
            onStep={(id) => setOpen((current) => current && { ...current, id })}
            onWithdraw={withdraw}
            request={shown}
            viewer={viewer}
          />
        </AppShell>
      </TooltipProvider>
    </MockupShell>
  )
}

"use client"

import * as React from "react"

import { FieldHint } from "@/components/design-system/field-hint"
import { FieldError, FieldLabel } from "@/components/ui/field"

/**
 * A field's label line: the label, its (i) when it has one, and — when the
 * field is wrong — the error at the end of the same line.
 *
 * The error used to take a line of its own between the label and the box.
 * That kept it above the control, but it pushed the box down by a line, so in
 * a row of fields the one in trouble dropped out of line with its neighbours
 * and the whole form shifted the moment Create was pressed. On the label's
 * line it costs no height: the box stays where the reader left it, and the
 * message is still the first thing read after the field's name.
 *
 * The label keeps its own colour; the border and this message carry the
 * state. Keep messages short enough for the line — an instruction of a few
 * words ("Name the voice."). A long one wraps under itself at the end of the
 * line rather than pushing the label.
 *
 * Point the control at the message with `aria-describedby={errorId(id)}`.
 */
export function FieldHeader({
  children,
  htmlFor,
  hint,
  error,
}: {
  /** The label text. */
  children: React.ReactNode
  htmlFor: string
  /** An (i) explanation, for drawers and dialogs — see `FieldHint`. */
  hint?: string
  error?: string | null
}) {
  return (
    <div className="flex items-baseline justify-between gap-3">
      {hint ? (
        <FieldHint hint={hint} htmlFor={htmlFor}>
          {children}
        </FieldHint>
      ) : (
        <FieldLabel htmlFor={htmlFor}>{children}</FieldLabel>
      )}
      {error ? (
        <FieldError className="text-end" id={errorId(htmlFor)}>
          {error}
        </FieldError>
      ) : null}
    </div>
  )
}

export function errorId(htmlFor: string) {
  return `${htmlFor}-error`
}

"use client"

import {
  Alert02Icon,
  Archive02Icon,
  ArrowDataTransferVerticalIcon,
  ArrowDown01Icon,
  ArrowDownLeft01Icon,
  ArrowLeft01Icon,
  ArrowRight01Icon,
  ArrowUp01Icon,
  ArrowUpRight01Icon,
  BookOpen02Icon,
  Building02Icon,
  CallOutgoing01Icon,
  BubbleChatIcon,
  Calendar03Icon,
  Cancel01Icon,
  CancelCircleIcon,
  CheckmarkCircle02Icon,
  Clock01Icon,
  Coins01Icon,
  ColorsIcon,
  ComponentIcon,
  Copy01Icon,
  CopyLinkIcon as CopyLinkGlyph,
  CpuIcon,
  CubeIcon,
  DashboardSquare01Icon,
  Delete02Icon,
  Download01Icon,
  EaseCurveControlPointsIcon,
  FileValidationIcon,
  FilterIcon,
  Home01Icon,
  InformationCircleIcon,
  MoreHorizontalIcon,
  PencilEdit02Icon,
  PlayIcon,
  PlusSignIcon,
  RefreshIcon,
  Robot01Icon,
  Search01Icon,
  SearchRemoveIcon,
  Tick02Icon,
  GlobalIcon,
  File01Icon,
  TextIcon,
  FolderAddIcon,
  FolderSyncIcon,
  ArrowLeft02Icon,
  ArrowRight02Icon,
  BankIcon,
  DashedLineCircleIcon,
  Hospital01Icon,
  RealEstate01Icon,
  Restaurant01Icon,
  ShoppingBag01Icon,
  SmartPhone01Icon,
  SparklesIcon,
  AlertCircleIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/* The icon rule's example: ordinary actions, because the point of that card is
   one size and one stroke weight rather than the glyphs themselves. */
export const PreviewIcon = icon(PlayIcon, "PreviewIcon")
export const NarrowIcon = icon(FilterIcon, "NarrowIcon")
export const ExportIcon = icon(Download01Icon, "ExportIcon")
export const DeleteIcon = icon(Delete02Icon, "DeleteIcon")

/** The two a row carries. Named for the row, not for the glyph. */
export const EditRowIcon = icon(PencilEdit02Icon, "EditRowIcon")

/** Sorting: the active direction, and the affordance on a column that is not sorted. */
export const SortAscIcon = icon(ArrowUp01Icon, "SortAscIcon")
export const SortDescIcon = icon(ArrowDown01Icon, "SortDescIcon")
export const SortableIcon = icon(ArrowDataTransferVerticalIcon, "SortableIcon")

/** Direction, which is what tells the two neutral chips apart. */
export const InboundIcon = icon(ArrowDownLeft01Icon, "InboundIcon")
export const OutboundIcon = icon(ArrowUpRight01Icon, "OutboundIcon")

/** The four call states. */
export const CompletedIcon = icon(CheckmarkCircle02Icon, "CompletedIcon")
export const FailedIcon = icon(CancelCircleIcon, "FailedIcon")
export const RunningIcon = icon(Clock01Icon, "RunningIcon")
export const ScheduledIcon = icon(Calendar03Icon, "ScheduledIcon")

/* The close control on the drawer demo's header — the house shape is a title,
   a description and this button, with no icon tile beside the title. */
export const CloseIcon = icon(Cancel01Icon, "CloseIcon")

export const RowMenuIcon = icon(MoreHorizontalIcon, "RowMenuIcon")
export const SearchIcon = icon(Search01Icon, "SearchIcon")

/* The multi-step form explains its fields with an (i) beside the label rather
   than a line under it — the reference it is built from does, and a screen
   uses one language for all of its fields or the other. */
export const HintIcon = icon(InformationCircleIcon, "HintIcon")
export const WarningIcon = icon(Alert02Icon, "WarningIcon")

/** A bare tick, for a step already done. `CompletedIcon` is a circled one and
    would sit inside the stepper's own circle. */
export const StepDoneIcon = icon(Tick02Icon, "StepDoneIcon")

/* The rail's disclosure chevron. It points down when the section is open and
   is rotated a quarter turn when it is not, so one glyph carries both states
   rather than two glyphs that have to be told apart. */
export const SectionToggleIcon = icon(ArrowDown01Icon, "SectionToggleIcon")

/* The tabs demo. One glyph per view of the same call, each naming what that
   view holds — the bar is the thing being demonstrated, so the labels carry
   an icon the way a real settings or record bar does. */
export const TranscriptIcon = icon(BubbleChatIcon, "TranscriptIcon")
export const ModelIcon = icon(CpuIcon, "ModelIcon")
export const CostIcon = icon(Coins01Icon, "CostIcon")

/* The header control that hands this exact topic to someone. The tick is the
   same glyph a finished step uses — one "done" mark across the reference,
   rather than a second one that has to be learned. */
export const CopyLinkIcon = icon(CopyLinkGlyph, "CopyLinkIcon")
export const CopiedIcon = icon(Tick02Icon, "CopiedIcon")

/* Copies a whole section out as a skill file. */
export const CopySkillIcon = icon(Copy01Icon, "CopySkillIcon")

/* The three states that are not the populated one, each named for the state
   rather than the glyph: nothing here yet, nothing matched, and it broke. */
export const NoResultsIcon = icon(SearchRemoveIcon, "NoResultsIcon")
export const SourceIcon = icon(BookOpen02Icon, "SourceIcon")
export const RetryIcon = icon(RefreshIcon, "RetryIcon")

/* The ring's way back up a level: from one section's topics to the five
   sections themselves. Named for where it goes rather than for the arrow,
   because the same glyph points back to two different places on this page. */
export const AllSectionsIcon = icon(ArrowLeft01Icon, "AllSectionsIcon")

/** The trailing mark on a section row on the overview. */
export const OpenSectionIcon = icon(ArrowRight01Icon, "OpenSectionIcon")

/* One per section on the overview. Named for the shelf, not the glyph, and
   present for the reason the house rules allow an icon in a list at all: five
   cards that differ only by a word are quicker to tell apart with a mark than
   without one. Nothing else on that page carries an icon. */
export const FoundationsIcon = icon(ColorsIcon, "FoundationsIcon")
export const MotionSectionIcon = icon(
  EaseCurveControlPointsIcon,
  "MotionSectionIcon",
)
export const PatternsIcon = icon(DashboardSquare01Icon, "PatternsIcon")
export const CustomComponentsIcon = icon(CubeIcon, "CustomComponentsIcon")
export const ShadcnComponentsIcon = icon(ComponentIcon, "ShadcnComponentsIcon")

/* The Icons tile's subject: one everyday glyph from the set the product draws
   from, set on its construction sheet by the tile's drawing. */
export const IconsTopicGlyph = icon(Home01Icon, "IconsTopicGlyph")

/* The index-page demo's header action. */
export const StartCallIcon = icon(CallOutgoing01Icon, "StartCallIcon")

/* The scenarios index: its two header tiles, the admin scope, and the row's
   one icon action. */
export const CreateScenarioIcon = icon(PlusSignIcon, "CreateScenarioIcon")
export const PlaygroundIcon = icon(Robot01Icon, "PlaygroundIcon")
export const OrganisationIcon = icon(Building02Icon, "OrganisationIcon")
export const CreateTemplateIcon = icon(FileValidationIcon, "CreateTemplateIcon")
export const ActiveIcon = icon(CheckmarkCircle02Icon, "ActiveIcon")
export const DeletedIcon = icon(Delete02Icon, "DeletedIcon")

/* The knowledge base's five ways in, as its header tiles. */
export const AddUrlIcon = icon(GlobalIcon, "AddUrlIcon")
export const AddFilesIcon = icon(File01Icon, "AddFilesIcon")
export const AddTextIcon = icon(TextIcon, "AddTextIcon")
export const CreateFolderIcon = icon(FolderAddIcon, "CreateFolderIcon")
export const SyncDocumentsIcon = icon(FolderSyncIcon, "SyncDocumentsIcon")

/* Surfaces: the demos under Components › Choosing a surface. */
export const ArchiveIcon = icon(Archive02Icon, "ArchiveIcon")
export const PreviousRecordIcon = icon(ArrowUp01Icon, "PreviousRecordIcon")
export const NextRecordIcon = icon(ArrowDown01Icon, "NextRecordIcon")
export const CreateInListIcon = icon(PlusSignIcon, "CreateInListIcon")
export const CopyKeyIcon = icon(Copy01Icon, "CopyKeyIcon")

/* Creation flow: the ways to start a scenario, and the industries its
   templates are filed under. */
export const StartBlankIcon = icon(DashedLineCircleIcon, "StartBlankIcon")
export const ChooseStartIcon = icon(ArrowRight02Icon, "ChooseStartIcon")
export const StepBackIcon = icon(ArrowLeft02Icon, "StepBackIcon")
export const BuildWithAiIcon = icon(SparklesIcon, "BuildWithAiIcon")
export const HealthcareIcon = icon(Hospital01Icon, "HealthcareIcon")
export const TelecomIcon = icon(SmartPhone01Icon, "TelecomIcon")
export const BankingIcon = icon(BankIcon, "BankingIcon")
export const RestaurantsIcon = icon(Restaurant01Icon, "RestaurantsIcon")
export const RetailIcon = icon(ShoppingBag01Icon, "RetailIcon")
export const RealEstateIcon = icon(RealEstate01Icon, "RealEstateIcon")

/* JSON: the fold toggle on an object's opening line, and copy. */
export const FoldIcon = icon(ArrowRight01Icon, "FoldIcon")
export const CopyJsonIcon = icon(Copy01Icon, "CopyJsonIcon")

/* Alerts: the error intent's glyph. Neutral, success and warning reuse
   HintIcon, CompletedIcon and WarningIcon. */
export const ErrorAlertIcon = icon(AlertCircleIcon, "ErrorAlertIcon")

import * as React from "react"

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { cn } from "@/lib/utils"

/**
 * The one table every reference list on this page is built from.
 *
 * Nearly all of them are the same three things — a specimen, its name, and
 * what it is for — and they had drifted into five different two-column grids
 * that each aligned slightly differently. One component means one row height,
 * one header treatment, and one place to change any of it.
 *
 * Cells take nodes, not strings, so a live demo sits in a column beside the
 * prose rather than in a separate block underneath it.
 */

export type ReferenceColumn = {
  header: string
  /**
   * A literal width class — Tailwind only emits a utility it can see spelled
   * out. Leave it off the column that should take the remaining width.
   */
  width?: string
}

export type ReferenceRow = {
  key: string
  cells: React.ReactNode[]
}

export function ReferenceTable({
  columns,
  rows,
}: {
  columns: ReferenceColumn[]
  rows: ReferenceRow[]
}) {
  return (
    <div className="overflow-hidden rounded-lg border">
      {/* Fixed layout, because the widths above are the whole point: with the
          default auto layout a long cell quietly widens its column and every
          table on the page ends up with its own proportions. */}
      <Table className="table-fixed">
        <TableHeader>
          <TableRow className="bg-muted/40 hover:bg-muted/40">
            {columns.map((column) => (
              <TableHead
                className={cn(
                  "h-11 px-4 text-xs font-medium text-muted-foreground",
                  column.width,
                )}
                key={column.header}
              >
                {column.header}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((row) => (
            <TableRow key={row.key}>
              {row.cells.map((cell, index) => (
                <TableCell
                  /* `whitespace-normal` undoes the primitive's nowrap, which
                     is right for a data row and wrong here — it lets prose
                     push a column past the width declared for it. */
                  className="px-4 py-3.5 align-top whitespace-normal"
                  key={columns[index]?.header ?? index}
                >
                  {cell}
                </TableCell>
              ))}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}

/**
 * A name in the column that names things — but only when the name is something
 * you type: a token, a class, a variant, a component. Mono is what says "this
 * is a literal", so spending it on an English word spends it for nothing.
 */
export function ReferenceName({ children }: { children: React.ReactNode }) {
  return <span className="font-mono text-sm">{children}</span>
}

/** The same column when the name is a word rather than a literal. */
export function ReferenceLabel({ children }: { children: React.ReactNode }) {
  return <span className="text-sm font-medium">{children}</span>
}

/** The prose column. Muted, because the name and the specimen lead. */
export function ReferenceNote({ children }: { children: React.ReactNode }) {
  return (
    <span className="text-sm leading-relaxed text-muted-foreground">
      {children}
    </span>
  )
}

