    <Badge className="bg-muted text-muted-foreground" variant="secondary">
      Active
    </Badge>
  )
}

"use client"

import * as React from "react"
import { toast } from "sonner"

import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { Field, FieldGroup, FieldLabel } from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemTitle,
} from "@/components/ui/item"
import { Textarea } from "@/components/ui/textarea"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { EditorHeader } from "@/components/mockups/config-versioning/editor-header"
import { HistoryDrawer } from "@/components/mockups/config-versioning/history-drawer"
import { SaveReview } from "@/components/mockups/config-versioning/save-review"
import { RequestDialog } from "@/components/mockups/publish-approval/request-dialog"
import type { Subject, Version } from "@/lib/mockups/config-versioning-data"
import {
  type ApprovalRequest,
  type CaseId,
  canDecide,
  SCENARIO_ORG,
  type Viewer,
  who,
} from "@/lib/mockups/publish-approval-data"

/**
 * DES-202's editor for a live scenario, with publishing replaced by a
 * request. Only the row under the header changes, and it carries every
 * approval state the editor has:
 *
 *  - Saves ahead of the version in use, nothing asked: which versions
 *    aren't in use, and Request approval — where DES-202 had Review and
 *    publish.
 *  - Waiting: which version, who asked, how long it has waited. View
 *    request opens the same record the approver reads; the approver sees
 *    "waiting for your approval" and Review.
 *  - Saved again while waiting: the request stays pinned to the version it
 *    was raised for — the client approves exactly what they read — and the
 *    row says the newer one isn't in it, with Request v15 instead.
 *  - Rejected: who, and their reason, until the next request.
 *  - Approved: nothing. The header already says who published the version
 *    in use.
 */
export function ApprovalEditor({
  subject,
  viewer,
  caseId,
  requests,
  onSave,
  onToggleLive,
  onRequest,
  onOpenRequest,
}: {
  /** As this viewer reads it — their own versions say You. */
  subject: Subject
  viewer: Viewer
  caseId: CaseId
  /** This scenario's requests, newest first. */
  requests: ApprovalRequest[]
  onSave: (
    body: Record<string, string>,
    editedFrom: number,
    note: string,
  ) => number
  onToggleLive: (on: boolean) => void
  /** Resolves false when sending failed. */
  onRequest: (request: {
    version: number
    summary: string
    note: string
  }) => Promise<boolean>
  onOpenRequest: (id: string) => void
}) {
  const newest = subject.versions[0]
  const [base, setBase] = React.useState(newest.n)
  const [draft, setDraft] = React.useState(newest.body)
  const [reviewing, setReviewing] = React.useState(false)
  const [history, setHistory] = React.useState(false)
  const [requestFor, setRequestFor] = React.useState<number | null>(null)

  const canEdit = caseId !== "view-only"
  const inUse = subject.inUse
  const pending = requests.find((request) => request.status === "pending")
  const rejected =
    !pending && requests[0]?.status === "rejected" ? requests[0] : null
  const ahead = subject.live ? subject.versions.filter((v) => v.n > inUse) : []
  const changes = subject.fields.filter(
    (field) => draft[field.id] !== newest.body[field.id],
  ).length

  function save(note: string) {
    const n = onSave(draft, base, note)
    setBase(n)
    setReviewing(false)
    toast.success(`Saved as v${n}`, {
      description: pending
        ? `It isn’t in the request for v${pending.version}. Callers still hear v${inUse}.`
        : `Callers still hear v${inUse}.`,
    })
  }

  function discard() {
    setDraft(newest.body)
    setBase(newest.n)
  }

  async function send(request: { summary: string; note: string }) {
    if (requestFor === null) return false
    const ok = await onRequest({ version: requestFor, ...request })
    if (ok) {
      toast.success(`Request sent to ${SCENARIO_ORG}`, {
        description: `Callers hear v${requestFor} once it’s approved.`,
      })
      setRequestFor(null)
    }
    return ok
  }

  return (
    <main className="mx-auto flex w-full max-w-3xl flex-col gap-6 p-8 pb-28">
      <EditorHeader
        base={base}
        canEdit={canEdit}
        onOpenHistory={() => setHistory(true)}
        onToggleLive={onToggleLive}
        subject={subject}
      />

      <StatusRow
        ahead={ahead}
        canRequest={canEdit}
        inUse={inUse}
        live={subject.live}
        newest={newest.n}
        onOpenRequest={onOpenRequest}
        onRequest={setRequestFor}
        pending={pending ?? null}
        rejected={rejected}
        viewer={viewer}
      />

      <FieldGroup>
        {subject.fields.map((field) => {
          const Control = field.multiline ? Textarea : Input
          return (
            <Field key={field.id}>
              <FieldLabel htmlFor={field.id}>{field.label}</FieldLabel>
              <Control
                dir="auto"
                disabled={!canEdit}
                id={field.id}
                onChange={(event) =>
                  setDraft((current) => ({
                    ...current,
                    [field.id]: event.target.value,
                  }))
                }
                {...(field.multiline ? { rows: 6 } : {})}
                value={draft[field.id]}
              />
            </Field>
          )
        })}
      </FieldGroup>

      {changes > 0 ? (
        <Card className="sticky bottom-4" size="sm">
          <CardContent className="flex items-center gap-3">
            <span className="text-sm tabular-nums">
              {changes === 1 ? "1 change" : `${changes} changes`}
            </span>
            <div className="ms-auto flex items-center gap-2">
              <Button onClick={discard} variant="ghost">
                Discard
              </Button>
              <Button onClick={() => setReviewing(true)}>
                Review and save
              </Button>
            </div>
          </CardContent>
        </Card>
      ) : null}

      <SaveReview
        base={base}
        draft={draft}
        liveLine={
          pending
            ? `Saving makes v${newest.n + 1}. It isn’t added to the request for v${pending.version}, and callers keep hearing v${inUse}.`
            : `Saving makes v${newest.n + 1}. Callers keep hearing v${inUse} until ${SCENARIO_ORG} approves a newer version.`
        }
        onOpenChange={setReviewing}
        onSave={save}
        open={reviewing}
        rival={null}
        subject={subject}
      />

      <HistoryDrawer
        approval={{
          by: SCENARIO_ORG,
          pending: pending?.version ?? null,
          onRequest: (n) => {
            setHistory(false)
            setRequestFor(n)
          },
        }}
        canEdit={canEdit}
        caseId="normal"
        editing={base}
        initial={{
          n: newest.n,
          against: inUse === newest.n ? null : inUse,
        }}
        onEditFrom={(n) => {
          const version = subject.versions.find((item) => item.n === n)
          if (!version) return
          setBase(n)
          setDraft(version.body)
          setHistory(false)
        }}
        onOpenChange={setHistory}
        onApply={async () => "failed"}
        open={history}
        subject={subject}
      />

      <RequestDialog
        caseId={caseId}
        live={inUse}
        onOpenChange={(open) => {
          if (!open) setRequestFor(null)
        }}
        onSend={send}
        open={requestFor !== null}
        org={SCENARIO_ORG}
        replacing={pending?.version ?? null}
        version={requestFor ?? newest.n}
      />
    </main>
  )
}

function StatusRow({
  ahead,
  inUse,
  live,
  newest,
  pending,
  rejected,
  viewer,
  canRequest,
  onRequest,
  onOpenRequest,
}: {
  ahead: Version[]
  inUse: number
  live: boolean
  newest: number
  pending: ApprovalRequest | null
  rejected: ApprovalRequest | null
  viewer: Viewer
  canRequest: boolean
  onRequest: (n: number) => void
  onOpenRequest: (id: string) => void
}) {
  if (!live) return null

  const request = (label: string, n: number) => (
    <RequestButton allowed={canRequest} onClick={() => onRequest(n)}>
      {label}
    </RequestButton>
  )

  if (pending) {
    const decides = canDecide(pending, viewer)
    const newer = newest > pending.version
    return (
      <Item variant="outline">
        <ItemContent>
          <ItemTitle className="tabular-nums">
            v{pending.version} is waiting for{" "}
            {decides ? "your" : `${SCENARIO_ORG}’s`} approval
          </ItemTitle>
          <ItemDescription className="tabular-nums">
            {newer
              ? `v${newest} was saved after the request and isn’t in it. Callers hear v${inUse}.`
              : `Requested by ${who(pending.by, viewer, true)}, ${pending.raised} · waiting ${pending.waiting}. Callers hear v${inUse}.`}
          </ItemDescription>
        </ItemContent>
        <ItemActions>
          <Button
            onClick={() => onOpenRequest(pending.id)}
            variant={decides || newer ? "outline" : "default"}
          >
            {decides ? "Review" : "View request"}
          </Button>
          {newer && !decides
            ? request(`Request v${newest} instead`, newest)
            : null}
        </ItemActions>
      </Item>
    )
  }

  if (rejected?.decision) {
    return (
      <Item variant="outline">
        <ItemContent>
          <ItemTitle className="tabular-nums">
            {who(rejected.decision.by, viewer)} rejected v{rejected.version}
          </ItemTitle>
          <ItemDescription className="tabular-nums" dir="auto">
            “{rejected.decision.reason}” Callers hear v{inUse}.
          </ItemDescription>
        </ItemContent>
        <ItemActions>
          <Button onClick={() => onOpenRequest(rejected.id)} variant="outline">
            View request
          </Button>
          {ahead.length > 0 ? request("Request approval", newest) : null}
        </ItemActions>
      </Item>
    )
  }

  if (ahead.length === 0) return null

  return (
    <Item variant="outline">
      <ItemContent>
        <ItemTitle className="tabular-nums">
          {ahead.length === 1
            ? `v${ahead[0].n} isn’t in use yet`
            : `v${ahead[ahead.length - 1].n} to v${ahead[0].n} aren’t in use yet`}
        </ItemTitle>
        <ItemDescription className="tabular-nums">
          Callers hear v{inUse} until {SCENARIO_ORG} approves a newer version.
        </ItemDescription>
      </ItemContent>
      <ItemActions>{request("Request approval", newest)}</ItemActions>
    </Item>
  )
}

/** Greyed for someone who can only view, saying why on hover. */
function RequestButton({
  allowed,
  onClick,
  children,
}: {
  allowed: boolean
  onClick: () => void
  children: React.ReactNode
}) {
  if (allowed) return <Button onClick={onClick}>{children}</Button>
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span className="flex">
          <Button disabled>{children}</Button>
        </span>
      </TooltipTrigger>
      <TooltipContent>
        You can view this scenario but not change it
      </TooltipContent>
    </Tooltip>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyTitle,
} from "@/components/ui/empty"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group"
import { Skeleton } from "@/components/ui/skeleton"
import {
  TableBody,
  TableCell,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { TabsContent } from "@/components/ui/tabs"
import {
  DataTable,
  DataTableHead,
  DataTableHeaderRow,
} from "@/components/shared/data-table"
import { ChoiceFilter, FilterBar } from "@/components/shared/filter-bar"
import { ListFooter } from "@/components/shared/list-footer"
import { PageHeader } from "@/components/shared/page-header"
import { PrimaryTabs } from "@/components/design-system/tabs-preview"
import { SearchRequestsIcon } from "@/components/mockups/publish-approval/icons"
import { StatusBadge } from "@/components/mockups/publish-approval/status-badge"
import {
  type ApprovalRequest,
  type CaseId,
  type Viewer,
  who,
} from "@/lib/mockups/publish-approval-data"

/**
 * Approvals — the page the PRD's mockups put in the nav, where the email and
 * the in-app notification both land. Every request the viewer can see: a
 * client sees their own organization's, Sarj staff every organization they
 * can access, so a requester and an approver read the same record.
 *
 * Laid out by the index page rules: tabs for the two views, search, filter
 * chips, the table, the pagination block. Waiting shows how long each has
 * waited (PRD); Closed shows the outcome and who closed it. A row opens the
 * request as a record drawer.
 */

const VIEWS = [
  { id: "waiting", label: "Waiting" },
  { id: "closed", label: "Closed" },
]

type Load = "loading" | "failed" | "ready"

export function ApprovalsPage({
  requests,
  viewer,
  caseId,
  onOpen,
}: {
  /** What this viewer can see, newest first. */
  requests: ApprovalRequest[]
  viewer: Viewer
  caseId: CaseId
  /** Opens one request; ↑ ↓ step through the list it was opened from. */
  onOpen: (id: string, list: string[]) => void
}) {
  const [view, setView] = React.useState("waiting")
  const [query, setQuery] = React.useState("")
  const [requester, setRequester] = React.useState<string | null>(null)
  const [load, setLoad] = React.useState<Load>("loading")
  const [attempt, setAttempt] = React.useState(0)

  React.useEffect(() => {
    const timer = setTimeout(
      () =>
        setLoad(caseId === "load-fails" && attempt === 0 ? "failed" : "ready"),
      600,
    )
    return () => clearTimeout(timer)
  }, [attempt, caseId])

  const requesters = [...new Set(requests.map((request) => request.by))].map(
    (name) => ({ value: name, label: who(name, viewer) }),
  )
  const matches = (request: ApprovalRequest) =>
    request.item.toLowerCase().includes(query.trim().toLowerCase()) &&
    (requester === null || request.by === requester)
  const filtering = query.trim() !== "" || requester !== null
  const clear = () => {
    setQuery("")
    setRequester(null)
  }

  const waiting = requests.filter((r) => r.status === "pending")
  const closed = requests.filter((r) => r.status !== "pending")

  return (
    <main className="mx-auto flex w-full max-w-350 flex-col gap-4 p-8">
      <PageHeader title="Approvals" />

      <PrimaryTabs
        items={VIEWS.map((entry) => ({
          ...entry,
          label:
            entry.id === "waiting" && load === "ready" && waiting.length > 0
              ? `Waiting · ${waiting.length}`
              : entry.label,
        }))}
        onValueChange={setView}
        value={view}
      >
        <div className="flex flex-col gap-2">
          <InputGroup className="min-w-64">
            <InputGroupAddon>
              <SearchRequestsIcon />
            </InputGroupAddon>
            <InputGroupInput
              aria-label="Search requests"
              onChange={(event) => setQuery(event.target.value)}
              placeholder="Search by scenario..."
              value={query}
            />
          </InputGroup>
          <FilterBar activeCount={requester ? 1 : 0}>
            <ChoiceFilter
              field="Requested by"
              onChange={setRequester}
              options={requesters}
              value={requester}
            />
          </FilterBar>
        </div>

        {load === "loading" ? (
          <TableSkeleton />
        ) : load === "failed" ? (
          <Empty>
            <EmptyHeader>
              <EmptyTitle>Couldn’t load requests</EmptyTitle>
              <EmptyDescription>
                Nothing was approved or rejected. Requests keep waiting until
                someone acts.
              </EmptyDescription>
            </EmptyHeader>
            <EmptyContent>
              <Button
                onClick={() => {
                  setLoad("loading")
                  setAttempt((count) => count + 1)
                }}
                size="lg"
                variant="outline"
              >
                Try again
              </Button>
            </EmptyContent>
          </Empty>
        ) : (
          <>
            <TabsContent value="waiting">
              <RequestTable
                closed={false}
                empty="Nothing waiting for approval"
                filtering={filtering}
                onClear={clear}
                onOpen={onOpen}
                rows={waiting.filter(matches)}
                viewer={viewer}
              />
            </TabsContent>
            <TabsContent value="closed">
              <RequestTable
                closed
                empty="No closed requests"
                filtering={filtering}
                onClear={clear}
                onOpen={onOpen}
                rows={closed.filter(matches)}
                viewer={viewer}
              />
            </TabsContent>
          </>
        )}
      </PrimaryTabs>
    </main>
  )
}

function RequestTable({
  rows,
  closed,
  viewer,
  empty,
  filtering,
  onClear,
  onOpen,
}: {
  rows: ApprovalRequest[]
  closed: boolean
  viewer: Viewer
  empty: string
  filtering: boolean
  onClear: () => void
  onOpen: (id: string, list: string[]) => void
}) {
  const [pageSize, setPageSize] = React.useState(10)

  if (rows.length === 0) {
    return (
      <Empty>
        <EmptyHeader>
          <EmptyTitle>{filtering ? "No requests match" : empty}</EmptyTitle>
        </EmptyHeader>
        {filtering ? (
          <EmptyContent>
            <Button onClick={onClear} variant="outline">
              Clear filters
            </Button>
          </EmptyContent>
        ) : null}
      </Empty>
    )
  }

  const visible = rows.slice(0, pageSize)
  const ids = visible.map((row) => row.id)

  return (
    <div className="flex flex-col gap-4">
      <DataTable>
        <TableHeader>
          <DataTableHeaderRow>
            <DataTableHead>Change</DataTableHead>
            {/* A client approves only their own organization's, so the
                column would say the same thing on every row. */}
            {viewer.sarj ? <DataTableHead>Approver</DataTableHead> : null}
            <DataTableHead>Requested by</DataTableHead>
            <DataTableHead>Raised</DataTableHead>
            {closed ? (
              <>
                <DataTableHead>Outcome</DataTableHead>
                <DataTableHead>Closed by</DataTableHead>
              </>
            ) : (
              <DataTableHead>Waiting</DataTableHead>
            )}
          </DataTableHeaderRow>
        </TableHeader>
        <TableBody>
          {visible.map((row) => (
            <TableRow
              className="cursor-pointer"
              key={row.id}
              onClick={() => onOpen(row.id, ids)}
              onKeyDown={(event) => {
                if (event.key === "Enter") onOpen(row.id, ids)
              }}
              tabIndex={0}
            >
              <TableCell className="font-medium tabular-nums">
                {row.item}{" "}
                <span className="font-normal text-muted-foreground">
                  v{row.version}
                </span>
              </TableCell>
              {viewer.sarj ? <TableCell>{row.org}</TableCell> : null}
              <TableCell>{who(row.by, viewer)}</TableCell>
              <TableCell className="text-muted-foreground tabular-nums">
                {row.raised}
              </TableCell>
              {closed ? (
                <>
                  <TableCell>
                    <StatusBadge status={row.status} />
                  </TableCell>
                  <TableCell className="text-muted-foreground tabular-nums">
                    {row.decision
                      ? `${who(row.decision.by, viewer)}, ${row.decision.at}`
                      : "—"}
                  </TableCell>
                </>
              ) : (
                <TableCell className="tabular-nums">{row.waiting}</TableCell>
              )}
            </TableRow>
          ))}
        </TableBody>
      </DataTable>

      <ListFooter
        from={1}
        noun="requests"
        onPageSizeChange={setPageSize}
        pageSize={pageSize}
        shown={visible.length}
        total={rows.length}
        atEnd={visible.length === rows.length}
      />
    </div>
  )
}

function TableSkeleton() {
  return (
    <div className="flex flex-col gap-2">
      {Array.from({ length: 5 }, (_, index) => (
        <Skeleton
          className="h-10 w-full motion-reduce:animate-none"
          key={index}
        />
      ))}
    </div>
  )
}

