} from "@/lib/mockups/publish-approval-data"

/**
 * One request, opened from the Approvals list, a notification or the
 * editor's pending row. A record drawer — 1024px, ↑ ↓ to the next request,
 * actions in the header, no footer — because the approver reads requests one
 * after another from a list, and the exact changes are a side-by-side diff
 * that does not fit in 448.
 *
 * Read order is the PRD's: the effect on callers first, written for someone
 * who is not technical; then why it is needed, in the requester's words;
 * then what it affects; the exact changes last, on expand.
 *
 * Who sees what:
 *  - The client's approver:
 *    Reject and Approve and publish. Approving publishes — there is no
 *    second step that could be forgotten, and no bypass (PRD).
 *  - The requester: Withdraw.
 *  - Anyone else: the decision buttons, greyed, saying who decides.
 */
export function ReviewDrawer({
  request,
  onClose,
  viewer,
  list,
  onStep,
  failApprove,
  onApprove,
  onReject,
  onWithdraw,
}: {
  request: ApprovalRequest | null
  onClose: () => void
  viewer: Viewer
  /** The requests ↑ and ↓ step through, in list order. */
  list: string[]
  onStep: (id: string) => void
  /** The approve-fails case: the first approve fails. */
  failApprove: boolean
  onApprove: (id: string) => Promise<boolean>
  onReject: (id: string, reason: string) => void
  onWithdraw: (id: string) => void
}) {
  const index = request ? list.indexOf(request.id) : -1
  const previous = index > 0 ? list[index - 1] : null
  const next = index >= 0 && index < list.length - 1 ? list[index + 1] : null

  React.useEffect(() => {
    if (!request) return
    function onKey(event: KeyboardEvent) {
      const target = event.target as HTMLElement
      if (target.closest("textarea, input")) return
      if (event.key === "ArrowUp" && previous) onStep(previous)
      if (event.key === "ArrowDown" && next) onStep(next)
    }
    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [request, previous, next, onStep])

  return (
    <Drawer
      direction="right"
      onOpenChange={(open) => {
        if (!open) onClose()
      }}
      open={request !== null}
    >
      <DrawerContent className="sm:max-w-5xl!">
        {request ? (
          <Review
            failApprove={failApprove}
            key={request.id}
            next={next}
            onApprove={onApprove}
            onReject={onReject}
            onStep={onStep}
            onWithdraw={onWithdraw}
            previous={previous}
            request={request}
            viewer={viewer}
          />
        ) : null}
      </DrawerContent>
    </Drawer>
  )
}

function Review({
  request,
  viewer,
  previous,
  next,
  onStep,
  failApprove,
  onApprove,
  onReject,
  onWithdraw,
}: {
  request: ApprovalRequest
  viewer: Viewer
  previous: string | null
  next: string | null
  onStep: (id: string) => void
  failApprove: boolean
  onApprove: (id: string) => Promise<boolean>
  onReject: (id: string, reason: string) => void
  onWithdraw: (id: string) => void
}) {
  const [rejecting, setRejecting] = React.useState(false)
  const [approving, setApproving] = React.useState(false)
  const [failed, setFailed] = React.useState(false)
  const attempts = React.useRef(0)

  const pending = request.status === "pending"
  const decides = canDecide(request, viewer)
  const mine = request.by === viewer.name
  const where = request.org

  async function approve() {
    setApproving(true)
    setFailed(false)
    attempts.current += 1
    const ok =
      failApprove && attempts.current === 1
        ? await new Promise<boolean>((resolve) =>
            setTimeout(() => resolve(false), 900),
          )
        : await onApprove(request.id)
    setApproving(false)
    if (!ok) setFailed(true)
  }

  return (
    <>
      <DrawerHeader className="flex flex-row items-start justify-between gap-4 border-b">
        <div className="flex min-w-0 flex-col gap-0.5">
          <DrawerTitle className="tabular-nums">
            {request.item} · v{request.version}
          </DrawerTitle>
          <DrawerDescription>
            {where} · requested by {who(request.by, viewer, true)},{" "}
            {request.raised}
          </DrawerDescription>
        </div>
        <div className="flex shrink-0 items-center gap-2">
          {pending && decides ? (
            <>
              <Button
                disabled={approving || rejecting}
                onClick={() => setRejecting(true)}
                variant="outline"
              >
                Reject
              </Button>
              <Button disabled={approving || rejecting} onClick={approve}>
                {approving ? <Spinner /> : null}
                {failed ? "Try again" : "Approve and publish"}
              </Button>
            </>
          ) : pending && mine ? (
            <Button onClick={() => onWithdraw(request.id)} variant="outline">
              Withdraw
            </Button>
          ) : pending ? (
            <Tooltip>
              <TooltipTrigger asChild>
                <span className="flex gap-2">
                  <Button disabled variant="outline">
                    Reject
                  </Button>
                  <Button disabled>Approve and publish</Button>
                </span>
              </TooltipTrigger>
              <TooltipContent>
                {`Only ${request.org}’s approvers can decide`}
              </TooltipContent>
            </Tooltip>
          ) : null}
          <Button
            aria-label="Previous request"
            disabled={!previous}
            onClick={() => previous && onStep(previous)}
            size="icon-sm"
            variant="ghost"
          >
            <PreviousRequestIcon />
          </Button>
          <Button
            aria-label="Next request"
            disabled={!next}
            onClick={() => next && onStep(next)}
            size="icon-sm"
            variant="ghost"
          >
            <NextRequestIcon />
          </Button>
          <DrawerClose asChild>
            <Button aria-label="Close" size="icon-sm" variant="ghost">
              <CloseIcon />
            </Button>
          </DrawerClose>
        </div>
      </DrawerHeader>

      <div className="flex flex-1 flex-col overflow-y-auto" data-vaul-no-drag>
        <div className="flex w-full max-w-3xl flex-col gap-6 p-6">
          <div className="flex flex-wrap items-center gap-2 text-sm text-muted-foreground tabular-nums">
            <StatusBadge status={request.status} />
            <Standing request={request} viewer={viewer} />
          </div>

          {failed ? (
            <Alert className="bg-destructive-tint" variant="destructive">
              <AlertTitle className="tabular-nums">
                Couldn’t approve v{request.version}
              </AlertTitle>
              <AlertDescription className="tabular-nums">
                Callers still hear v{request.live}. The request is still
                waiting.
              </AlertDescription>
            </Alert>
          ) : null}

          {rejecting ? (
            <RejectReason
              onCancel={() => setRejecting(false)}
              onReject={(reason) => onReject(request.id, reason)}
              version={request.version}
            />
          ) : null}

          {request.status === "rejected" && request.decision?.reason ? (
            <Block
              label={`Reason from ${who(request.decision.by, viewer, true)}`}
            >
              {request.decision.reason}
            </Block>
          ) : null}

          <Block label="What callers will notice">
            <span className="text-base">{request.summary}</span>
          </Block>

          <Block
            label={`Why it’s needed, from ${who(request.by, viewer, true)}`}
          >
            {request.note}
          </Block>

          <dl className="grid grid-cols-[auto_1fr] gap-x-6 gap-y-2 text-sm">
            <dt className="text-muted-foreground">Affects</dt>
            <dd>{`Every call to ${request.item}`}</dd>
            <dt className="text-muted-foreground">Version</dt>
            <dd className="tabular-nums">
              v{request.live} → v{request.version}
            </dd>
          </dl>

          <ExactChanges request={request} />
        </div>
      </div>
    </>
  )
}

/** One line on where the request stands: how long it has waited, or who
 *  closed it and when. */
function Standing({
  request,
  viewer,
}: {
  request: ApprovalRequest
  viewer: Viewer
}) {
  const decision = request.decision
  switch (request.status) {
    case "pending":
      return (
        <span>
          Waiting {request.waiting} · callers hear v{request.live} until it’s
          approved
        </span>
      )
    case "approved":
      return (
        <span>
          {who(decision!.by, viewer)}, {decision!.at} · callers hear v
          {request.version} from then
        </span>
      )
    case "rejected":
    case "withdrawn":
      return (
        <span>
          {who(decision!.by, viewer)}, {decision!.at}
        </span>
      )
  }
}

function Block({
  label,
  children,
}: {
  label: string
  children: React.ReactNode
}) {
  return (
    <section className="flex flex-col gap-1">
      <h3 className="text-sm text-muted-foreground">{label}</h3>
      <p className="text-sm" dir="auto">
        {children}
      </p>
    </section>
  )
}

/**
 * Reject asks for a reason, inline at the top of the record rather than in
 * a dialog over the drawer (one overlay at a time). The reason goes back to
 * the requester with the rejection.
 */
function RejectReason({
  version,
  onCancel,
  onReject,
}: {
  version: number
  onCancel: () => void
  onReject: (reason: string) => void
}) {
  const [reason, setReason] = React.useState("")
  const [submitted, setSubmitted] = React.useState(false)
  const error =
    submitted && reason.trim() === "" ? "Say what needs to change." : null

  return (
    <Card>
      <CardContent>
        <Field>
          <FieldHeader error={error} htmlFor="reject-reason">
            Why you’re rejecting it
          </FieldHeader>
          <Textarea
            aria-describedby={error ? errorId("reject-reason") : undefined}
            aria-invalid={error ? true : undefined}
            autoFocus
            dir="auto"
            id="reject-reason"
            onChange={(event) => setReason(event.target.value)}
            placeholder="Keep the 1 to 10 scale until the branch reports switch over."
            rows={3}
            value={reason}
          />
        </Field>
      </CardContent>
      <CardFooter className="justify-end gap-2">
        <Button onClick={onCancel} variant="outline">
          Cancel
        </Button>
        <Button
          onClick={() => {
            setSubmitted(true)
            if (reason.trim()) onReject(reason.trim())
          }}
        >
          Reject v{version}
        </Button>
      </CardFooter>
    </Card>
  )
}

/** The exact changes, closed until asked for (PRD: "on expand"). */
function ExactChanges({ request }: { request: ApprovalRequest }) {
  const [open, setOpen] = React.useState(false)

  return (
    <Collapsible
      className="flex flex-col gap-4"
      onOpenChange={setOpen}
      open={open}
    >
      <CollapsibleTrigger asChild>
        <Button className="self-start" variant="outline">
          {open ? "Hide exact changes" : "Show exact changes"}
        </Button>
      </CollapsibleTrigger>
      <CollapsibleContent className="flex flex-col gap-6">
        {request.changes.map((change) => (
          <div className="flex flex-col gap-2" key={change.label}>
            <span className="text-sm font-medium">{change.label}</span>
            <div className="grid grid-cols-2 text-xs text-muted-foreground tabular-nums">
              <span className="px-3">
                v{request.live}
                {request.status === "pending" ? ", live" : ""}
              </span>
              <span className="px-3">v{request.version}</span>
            </div>
            <SideBySideDiff after={change.after} before={change.before} />
          </div>
        ))}
      </CollapsibleContent>
    </Collapsible>
  )
}

import { Badge } from "@/components/ui/badge"
import type { Status } from "@/lib/mockups/publish-approval-data"

const LOOK: Record<Status, { label: string; className: string }> = {
  pending: {
    label: "In review",
    className: "bg-warning-tint text-warning-tint-foreground",
  },
  approved: {
    label: "Approved",
    className: "bg-success-tint text-success-tint-foreground",
  },
  rejected: {
    label: "Rejected",
    className: "bg-destructive-tint text-destructive-tint-foreground",
  },
  withdrawn: {
    label: "Withdrawn",
    className: "bg-muted text-muted-foreground",
  },
}

/**
 * Where a request is. "In review" is the short name for waiting on an
 * approval, short because it shares a table cell with Live. It takes the
 * warning tint because it is the one a reader has to act on or wait for;
 * Withdrawn is muted because nothing follows from it.
 */
export function StatusBadge({ status }: { status: Status }) {
  const look = LOOK[status]
  return (
    <Badge className={look.className} variant="secondary">
      {look.label}
    </Badge>
  )
}

import * as React from "react"

import { Table, TableHead, TableRow } from "@/components/ui/table"
import { cn } from "@/lib/utils"

/**
 * The table shape the platform-consistency pass settled on, taken verbatim
 * from the product's `vnagar/platform-consistency` branch (then `sarj-ai/bulbul`,
 * now `sarj-ai/platform`):
 *
 *  - a bordered, radiused container with no padding of its own, so the header
 *    band reaches the edge instead of floating inside an inset;
 *  - a shaded header row that stays shaded on hover, so the band reads as
 *    chrome rather than a row you can click;
 *  - header labels at full-strength foreground and semibold, not muted;
 *  - a fixed 40px row on 16px cell padding, so rows do not grow with their
 *    content and the header lines up with the body.
 *
 * On that branch only `call-activity-table.tsx` had been brought across — the
 * trunk assignments and provisioned tables were still on plain `<TableHead>`
 * inside a `rounded-md border`. All three use it here.
 */
export function DataTable({
  className,
  children,
}: {
  className?: string
  children: React.ReactNode
}) {
  return (
    <div className="overflow-hidden rounded-lg border">
      <Table className={cn("[&_td]:h-10 [&_td]:px-4 [&_th]:px-4", className)}>
        {children}
      </Table>
    </div>
  )
}

export function DataTableHeaderRow({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <TableRow className="bg-muted/50 hover:bg-muted/50">{children}</TableRow>
  )
}

export function DataTableHead({
  className,
  children,
}: {
  className?: string
  children: React.ReactNode
}) {
  return (
    <TableHead className={cn("font-semibold text-foreground", className)}>
      {children}
    </TableHead>
  )
}

