export type CaseId =
  | "normal"
  | "pending"
  | "newer"
  | "rejected"
  | "summary-writing"
  | "summary-failed"
  | "send-fails"
  | "approve-fails"
  | "load-fails"
  | "empty"
  | "view-only"

